import{_ as o,c as i,e,f as n,u as l,L as b,g as p,E as h,h as r,o as u}from"./index-DM3R47Z4.js";const m={class:"welcome-container"},_={class:"welcome-nav"},g={class:"nav-left"},w=["src"],k={__name:"HomePage",setup(L){const a=r(),t=()=>{a.push("/contract")},s=()=>{a.push("/chat")},d=()=>{p()?h({message:"您已登录，若要切换账号请在个人中心退出当前帐号",type:"warning"}):a.push("/auth")},c=()=>{a.push("/profile")};return(v,f)=>(u(),i("div",m,[e("nav",_,[e("div",g,[e("img",{class:"avatar",src:l(b),alt:"LawReasonerAvatar"},null,8,w),f[0]||(f[0]=e("span",{class:"nav-logo"},"法理智推",-1))]),e("div",{class:"nav-right"},[e("button",{class:"nav-button",onClick:d},"登录/注册"),e("button",{class:"nav-button",onClick:c},"个人中心"),e("button",{class:"nav-button",onClick:s},"开始咨询"),e("button",{class:"nav-button",onClick:t},"合同生成")])]),f[1]||(f[1]=n('<div class="welcome-header" data-v-bf5effe8><h1 class="welcome-title" data-v-bf5effe8>欢迎使用法理智推</h1><p class="welcome-subtitle" data-v-bf5effe8>智能法律推理系统，助力法律资源公平分配与效率提升</p></div><div class="welcome-content" data-v-bf5effe8><section class="welcome-section" data-v-bf5effe8><h2 class="section-title" data-v-bf5effe8>系统功能概述</h2><div class="section-content" data-v-bf5effe8><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>智能法律咨询</h3><p data-v-bf5effe8>基于大语言模型的民事法律智能咨询系统，分析案情并给出合理判决结果，提供多轮对话，支持会话管理。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>《民法典》知识库</h3><p data-v-bf5effe8>提供完整的《民法典》条文查询与浏览，按章节分类展示，支持关键词搜索，快速定位相关法条。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>智能合同生成</h3><p data-v-bf5effe8>基于用户对话描述，智能推荐合适的合同模板，支持多种常用合同类型，自动填写合同内容，生成专业法律文书。</p></div></div></section><section class="welcome-section" data-v-bf5effe8><h2 class="section-title" data-v-bf5effe8>法律领域背景分析</h2><div class="section-content" data-v-bf5effe8><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>法律资源分配不均</h3><p data-v-bf5effe8>我国法律资源分配不均，大多数律师集中在东部发达地区，基层（尤其是中西部和农村）法律服务资源匮乏。京沪等一线城市律所的“虹吸效应”显著，中小型律所倾向于并入全国性大所，进一步加剧资源集中。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>法律知识普及困难</h3><p data-v-bf5effe8>《民法典》共有1260条法规，公众对其中的具体内容的掌握程度还有较大提升空间。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>政策支持</h3><p data-v-bf5effe8>《智慧法院建设规划》明确提出AI辅助审判要求：“构建面向各类用户的人工智能感知交互体系和以知识为中心的人工智能辅助决策体系”。</p></div></div></section><section class="welcome-section" data-v-bf5effe8><h2 class="section-title" data-v-bf5effe8>技术突破机遇</h2><div class="section-content" data-v-bf5effe8><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>深度思考基础开源模型</h3><p data-v-bf5effe8>本系统采用deepseek-r1开源模型，结合思维链(CoT)技术训练，实现了法律案例的多步推理分析，准确抓取案件关键信息并给出合理判断。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>检索增强生成(RAG)技术</h3><p data-v-bf5effe8>运用all-MiniLM-L6-v2向量模型建立合同知识库，实现从用户描述到合适合同模板的精准匹配，语义理解准确率大幅提升。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>现代化系统架构</h3><p data-v-bf5effe8>采用模块化设计理念，实现系统各功能单元的解耦与协同，确保用户体验流畅的同时提供高效稳定的服务，支持未来功能的灵活扩展与优化。</p></div></div></section><section class="welcome-section" data-v-bf5effe8><h2 class="section-title" data-v-bf5effe8>&quot;法理智推&quot;系统的独特性</h2><div class="section-content" data-v-bf5effe8><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>法律思维链推理</h3><p data-v-bf5effe8>系统基于deepseek模型，采用特定的法律推理思维链模板，模拟法官&quot;识别关键信息-引用法律依据-逐步推理-得出结论&quot;的思考过程，确保推理结果的可解释性。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>智能合同匹配生成</h3><p data-v-bf5effe8>独创的合同RAG知识库结合all-MiniLM-L6-v2模型，从用户描述中精准提取关键信息，智能匹配最适合的合同模板，实现定制化合同生成。</p></div><div class="card" data-v-bf5effe8><h3 data-v-bf5effe8>《民法典》全文语义检索</h3><p data-v-bf5effe8>系统内置完整《民法典》文本，支持用户进行搜索和查询，助力普法教育。</p></div></div></section></div><div class="welcome-footer" data-v-bf5effe8><p data-v-bf5effe8>法理智推 —— 让法律更智能，让正义更高效</p><div class="author-info" data-v-bf5effe8><h3 data-v-bf5effe8>开发者信息</h3><p data-v-bf5effe8>姓名：powderblueX、zhu mingcan</p><p data-v-bf5effe8>邮箱：mishijibai@163.com</p><p data-v-bf5effe8>地址：上海市嘉定区曹安公路4800号</p></div></div>',3))]))}},T=o(k,[["__scopeId","data-v-bf5effe8"]]);export{T as default};
